b_general_wage_threshold = residual("s4", "during the calendar year or the preceding calendar year paid wages of $1,500 or more")
b_general_day_threshold = residual("s5", "on each of some 10 days during the calendar year or during the preceding calendar year, each day being in a different calendar week, employed at least one individual in employment for some portion of the day")
b_domestic_services = observation(entity="Bob", entity_source="s52", predicate="performing domestic services referred to in paragraph (3)", predicate_source="s6")
